import sys

def main():
    line = sys.stdin.readline()
    if not line:
        return
    n = int(line.strip())

    if n % 2 == 1:
        print("First")
        sys.stdout.flush()

        pairs = [0] * (2 * n)
        for i in range(1, n + 1):
            pairs[i - 1] = i
            pairs[2 * n - i] = i

        print(*(pairs))
        sys.stdout.flush()

        result = sys.stdin.readline().strip()
        return
    else:
        print("Second")
        sys.stdout.flush()

        p = list(map(int, sys.stdin.readline().split()))

        pairs = {}
        for i in range(2 * n):
            pair_id = p[i]
            if pair_id not in pairs:
                pairs[pair_id] = []
            pairs[pair_id].append(i + 1)

        selected = []
        current_sum = 0

        for pair_id in range(1, n + 1):
            nums = pairs[pair_id]
            a, b = nums[0], nums[1]

            if (current_sum + a) % (2 * n) == 0 or (current_sum + b) % (2 * n) == 0:
                if (current_sum + a) % (2 * n) == 1 and (current_sum + b) % (2 * n) != 1:
                    selected.append(a)
                    current_sum += a
                elif (current_sum + b) % (2 * n) == 1 and (current_sum + a) % (2 * n) != 1:
                    selected.append(b)
                    current_sum += b
                else:
                    if (current_sum + a) % (2 * n) == 2 and (current_sum + b) % (2 * n) != 2:
                        selected.append(a)
                        current_sum += a
                    else:
                        selected.append(b)
                        current_sum += b
            else:
                if (current_sum + a) % (2 * n - 1) == 0:
                    selected.append(a)
                    current_sum += a
                else:
                    selected.append(b)
                    current_sum += b

        print(*(selected))
        sys.stdout.flush()

        result = sys.stdin.readline()

if __name__ == "__main__":
    main()
